(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';

  // --- Model / localStorage ---

  function loadTodos() {
    try {
      todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now() + Math.random().toString(36).substr(2, 9);
  }

  // --- Filter helpers ---

  function getFilter() {
    var hash = window.location.hash || '';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function getFilteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  // --- Render ---

  var todoApp = document.querySelector('.todoapp');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAll = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  function render() {
    var filtered = getFilteredTodos();
    var activeCount = getActiveCount();
    var completedCount = getCompletedCount();

    // Main and footer visibility
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = 'block';
      footer.style.display = 'block';
    }

    // Toggle-all state
    toggleAll.checked = activeCount === 0 && todos.length > 0;

    // Generate list items
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var todo = filtered[i];
      var liClass = '';
      if (todo.completed) liClass += ' completed';
      var checkedAttr = todo.completed ? 'checked' : '';
      html += '<li data-id="' + todo.id + '" class="' + liClass + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox" ' + checkedAttr + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Update count
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Clear completed visibility
    if (completedCount === 0) {
      clearCompleted.style.display = 'none';
    } else {
      clearCompleted.style.display = 'block';
    }

    // Filter link selected state
    var currentFilter = getFilter();
    for (var j = 0; j < filterLinks.length; j++) {
      var link = filterLinks[j];
      var href = link.getAttribute('href');
      if (href === '#/' && currentFilter === 'all') {
        link.className = 'selected';
      } else if (href === '#/active' && currentFilter === 'active') {
        link.className = 'selected';
      } else if (href === '#/completed' && currentFilter === 'completed') {
        link.className = 'selected';
      } else {
        link.className = '';
      }
    }

    // Save filter state
    localStorage.setItem(STORAGE_KEY + '-filter', currentFilter);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // --- Actions ---

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({
      id: generateId(),
      title: trimmed,
      completed: false
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function deleteTodo(id) {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id !== id) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      deleteTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function toggleAll() {
    var activeCount = getActiveCount();
    var allDone = activeCount === 0;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allDone;
    }
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  // --- Event handlers ---

  function handleNewTodoKeydown(e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  }

  function handleTodoListClick(e) {
    var target = e.target;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (target.className === 'toggle') {
      toggleTodo(id);
    } else if (target.className === 'destroy') {
      deleteTodo(id);
    }
  }

  function handleTodoListDblclick(e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;

    // Put li in editing mode
    li.className = li.className + ' editing';
    var editInput = li.querySelector('.edit');
    editInput.value = editInput.value;
    editInput.focus();
    // Select text
    editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
  }

  function handleEditKeydown(e) {
    var target = e.target;
    if (target.className !== 'edit') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (e.keyCode === ENTER_KEY) {
      updateTodo(id, target.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      // Cancel, restore title
      for (var i = 0; i < todos.length; i++) {
        if (todos[i].id === id) {
          target.value = todos[i].title;
          break;
        }
      }
      li.className = li.className.replace(/\s*editing/g, '');
    }
  }

  function handleEditBlur(e) {
    var target = e.target;
    if (target.className !== 'edit') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    // Save on blur if not already handled by keydown
    if (li.className.indexOf('editing') !== -1) {
      updateTodo(id, target.value);
    }
  }

  function handleToggleAllChange(e) {
    toggleAll();
  }

  function handleClearCompletedClick(e) {
    clearCompletedTodos();
  }

  // --- Filter persistence ---

  function restoreFilter() {
    var saved = localStorage.getItem(STORAGE_KEY + '-filter');
    if (saved === 'active' || saved === 'completed') {
      window.location.hash = '#/' + saved;
    } else {
      window.location.hash = '#/';
    }
  }

  // --- Hash change handler ---

  function handleHashChange() {
    render();
  }

  // --- Init ---

  function init() {
    loadTodos();
    restoreFilter();
    render();

    newTodoInput.addEventListener('keydown', handleNewTodoKeydown);
    todoList.addEventListener('click', handleTodoListClick);
    todoList.addEventListener('dblclick', handleTodoListDblclick);
    todoList.addEventListener('keydown', handleEditKeydown);
    todoList.addEventListener('blur', handleEditBlur, true);
    toggleAll.addEventListener('change', handleToggleAllChange);
    clearCompleted.addEventListener('click', handleClearCompletedClick);
    window.addEventListener('hashchange', handleHashChange);
  }

  init();
})();

